// Global holds mesh-wide tuning parameters.
type Global struct {
        HealthIntervalMs        int `toml:"health_interval_ms"`
        UnhealthyThreshold      int `toml:"unhealthy_threshold"`
        HealthyThreshold        int `toml:"healthy_threshold"`
        StatsWindowSec          int `toml:"stats_window_sec"`
        CircuitBreakerThreshold int `toml:"circuit_breaker_threshold"`
        CircuitBreakerTimeoutMs int `toml:"circuit_breaker_timeout_ms"`
}

// Endpoint describes one backend endpoint from config.
type Endpoint struct {
        Address          string `toml:"address"`
        Weight           int    `toml:"weight"`
        WarmupDurationMs int    `toml:"warmup_duration_ms"`
        HealthCheck      string `toml:"health_check"`
        HealthPath       string `toml:"health_path"`
        HealthCmd        string `toml:"health_cmd"`
}

// Service describes one routed service from config.
type Service struct {
        Name                      string     `toml:"name"`
        ListenPort                int        `toml:"listen_port"`
        RoutingMode               string     `toml:"routing_mode"`
        DrainTimeoutMs            int        `toml:"drain_timeout_ms"`
        MaxConnectionsPerEndpoint int        `toml:"max_connections_per_endpoint"`
        ConnectionLimitMode       string     `toml:"connection_limit_mode"`
        RateLimitRps              int        `toml:"rate_limit_rps"`
        RateLimitBurst            int        `toml:"rate_limit_burst"`
        RateLimitQueueDepth       int        `toml:"rate_limit_queue_depth"`
        RateLimitQueueTimeoutMs   int        `toml:"rate_limit_queue_timeout_ms"`
        MaxRetries                int        `toml:"max_retries"`
        RetryDelayMs              int        `toml:"retry_delay_ms"`
        RetryBackoffMultiplier    float64    `toml:"retry_backoff_multiplier"`
        RetryMaxDelayMs           int        `toml:"retry_max_delay_ms"`
        IdleTimeoutMs             int        `toml:"idle_timeout_ms"`
        Endpoints                 []Endpoint `toml:"endpoint"`
}

// Config is the parsed application configuration.
type Config struct {
        Global   Global
        Services []Service `toml:"service"`
}

// Load reads and normalizes a TOML config file.
func Load(path string) (*Config, error) {
        var cfg Config
        if _, err := toml.DecodeFile(path, &cfg); err != nil {
                return nil, err
        }
        if cfg.Global.HealthIntervalMs <= 0 {
                cfg.Global.HealthIntervalMs = 2000
        }
        if cfg.Global.UnhealthyThreshold <= 0 {
                cfg.Global.UnhealthyThreshold = 3
        }
        if cfg.Global.HealthyThreshold <= 0 {
                cfg.Global.HealthyThreshold = 2
        }
        if cfg.Global.StatsWindowSec <= 0 {
                cfg.Global.StatsWindowSec = 60
        }
        if cfg.Global.CircuitBreakerThreshold <= 0 {
                cfg.Global.CircuitBreakerThreshold = 3
        }
        if cfg.Global.CircuitBreakerTimeoutMs <= 0 {
                cfg.Global.CircuitBreakerTimeoutMs = 5000
        }
        for i := range cfg.Services {
                s := &cfg.Services[i]
                if s.RoutingMode == "" {
                        s.RoutingMode = "weighted-round-robin"
                }
                if s.DrainTimeoutMs <= 0 {
                        s.DrainTimeoutMs = 5000
                }
                if s.MaxConnectionsPerEndpoint <= 0 {
                        s.MaxConnectionsPerEndpoint = 100
                }
                if s.ConnectionLimitMode == "" {
                        s.ConnectionLimitMode = "per-endpoint"
                }
                if s.RateLimitBurst <= 0 {
                        s.RateLimitBurst = s.RateLimitRps
                }
                if s.RateLimitQueueTimeoutMs <= 0 {
                        s.RateLimitQueueTimeoutMs = 1000
                }
                if s.RetryDelayMs <= 0 {
                        s.RetryDelayMs = 100
                }
                if s.RetryBackoffMultiplier <= 0 {
                        s.RetryBackoffMultiplier = 2.0
                }
                if s.RetryMaxDelayMs <= 0 {
                        s.RetryMaxDelayMs = 5000
                }
                for j := range s.Endpoints {
                        ep := &s.Endpoints[j]
                        if ep.HealthCheck == "" {
                                ep.HealthCheck = "tcp"
                        }
                        if ep.Weight < 0 {
                                ep.Weight = 0
                        }
                        if ep.WarmupDurationMs < 0 {
                                ep.WarmupDurationMs = 0
                        }
                }
        }
        return &cfg, nil
}
