// CheckDependency returns whether a dependency service is available and how
// many of its endpoints are healthy with closed circuit breakers.
func (s *State) CheckDependency(name string) (bool, int) {
        dep := s.GetService(name)
        if dep == nil {
                return false, 0
        }
        dep.mu.Lock()
        defer dep.mu.Unlock()
        healthy := 0
        for _, ep := range dep.Endpoints {
                if ep.State == Healthy && ep.Circuit.IsClosed() {
                        healthy++
                }
        }
        return healthy > 0, healthy
}

// CheckDependencies returns the first unavailable dependency and the full
// dependency status list for a service.
func (s *State) CheckDependencies(service string) (string, []DependencyStatus) {
        ss := s.GetService(service)
        if ss == nil {
                return "", nil
        }
        ss.mu.Lock()
        deps := ss.DependsOn
        ss.mu.Unlock()
        if len(deps) == 0 {
                return "", nil
        }
        var statuses []DependencyStatus
        var failed string
        for _, dep := range deps {
                available, healthy := s.CheckDependency(dep)
                statuses = append(statuses, DependencyStatus{Name: dep, Available: available, HealthyEndpoints: healthy})
                if failed == "" && !available {
                        failed = dep
                }
        }
        return failed, statuses
}

// DependencyStatuses returns dependency status rows for a service.
func (s *State) DependencyStatuses(service string) []DependencyStatus {
        _, statuses := s.CheckDependencies(service)
        return statuses
