// removeDependencyCycles drops dependency edges that would create cycles.
func removeDependencyCycles(services []Service) []Service {
        byName := make(map[string]int, len(services))
        for i, svc := range services {
                byName[svc.Name] = i
        }
        for i := range services {
                seen := map[string]bool{services[i].Name: true}
                kept := make([]string, 0, len(services[i].DependsOn))
                for _, dep := range services[i].DependsOn {
                        if dep == services[i].Name {
                                log.Printf("warning: dropping self dependency from %s to %s", services[i].Name, dep)
                                continue
                        }
                        if _, ok := byName[dep]; !ok {
                                kept = append(kept, dep)
                                continue
                        }
                        if createsCycle(services, byName, seen, services[i].Name, dep) {
                                log.Printf("warning: dropping dependency edge from %s to %s to avoid circular dependency", services[i].Name, dep)
                                continue
                        }
                        kept = append(kept, dep)
                }
                services[i].DependsOn = kept
        }
        return services
}

func createsCycle(services []Service, byName map[string]int, seen map[string]bool, start, dep string) bool {
        if seen[dep] {
                return true
        }
        seen[dep] = true
        defer delete(seen, dep)
        next := services[byName[dep]].DependsOn
        for _, d := range next {
                if d == start || d == dep {
                        return true
                }
                if _, ok := byName[d]; !ok {
                        continue
                }
                if createsCycle(services, byName, seen, start, d) {
                        return true
                }
        }
        return false
}
