                }
        }
        if len(rows) == 0 {
                return "no dependencies", nil
        }
        var b strings.Builder
        fmt.Fprintf(&b, "%-14s %-14s %-10s %-18s\\n", "SERVICE", "DEPENDS_ON", "AVAILABLE", "HEALTHY_ENDPOINTS")
        for _, row := range rows {
                fmt.Fprintf(&b, "%-14s %-14s %-10t %-18d\\n", row.Service, row.Name, row.Available, row.HealthyEndpoints)
        }
        return strings.TrimRight(b.String(), "\\n"), nil
}

